// Audience Network leak detector - tune here.
// RESULT_ACTIONS = every event that counts as a conversion (leads, registrations,
// purchases); the workflow sums whichever are present, so it fits lead-gen and ecommerce.
return [{ json: {
  DATE_PRESET: 'last_30d',
  SPEND_FLOOR: 50,        // ignore Audience Network slices spending less than this
  CPA_MULTIPLE: 1.5,      // flag AN when its cost-per-result is this many times the non-AN benchmark
  MIN_BENCH_RESULTS: 3,   // need at least this many non-AN results before trusting the benchmark
  RESULT_ACTIONS: [
    'offsite_complete_registration_add_meta_leads', 'lead', 'leadgen_grouped',
    'onsite_conversion.lead_grouped', 'omni_complete_registration', 'complete_registration',
    'omni_purchase', 'offsite_conversion.fb_pixel_purchase', 'purchase',
  ],
} }];

// Separate Audience Network slices from the rest, compute cost-per-result for each,
// and flag AN spend that underperforms the non-AN benchmark or converts nothing.
const cfg = $('Set config: results & AN thresholds').first().json;
const RES = new Set(cfg.RESULT_ACTIONS);
const rows = $json.data || [];
const resultsOf = (actions) => Array.isArray(actions)
  ? actions.filter((a) => RES.has(a.action_type)).reduce((n, a) => n + (Number(a.value) || 0), 0)
  : 0;

let anSpend = 0, anResults = 0, restSpend = 0, restResults = 0;
const anSlices = [];
for (const r of rows) {
  const spend = Number(r.spend) || 0;
  const results = resultsOf(r.actions);
  if (r.publisher_platform === 'audience_network') {
    anSpend += spend; anResults += results;
    anSlices.push({
      placement: `${r.publisher_platform} / ${r.platform_position}`,
      spend: +spend.toFixed(2),
      results,
      cpa: results > 0 ? +(spend / results).toFixed(2) : null,
    });
  } else { restSpend += spend; restResults += results; }
}
const benchCPA = (restResults >= cfg.MIN_BENCH_RESULTS && restResults > 0)
  ? +(restSpend / restResults).toFixed(2) : null;

const leaks = [];
for (const s of anSlices) {
  if (s.spend < cfg.SPEND_FLOOR) continue;
  const zeroResults = s.results === 0;
  const overBench = benchCPA != null && s.cpa != null && s.cpa >= benchCPA * cfg.CPA_MULTIPLE;
  if (!zeroResults && !overBench) continue;
  const recoverable = zeroResults ? s.spend : (s.spend - benchCPA * s.results);
  leaks.push({
    ...s,
    benchmark_cpa: benchCPA,
    reason: zeroResults ? 'spend with zero results' : `CPA $${s.cpa} vs benchmark $${benchCPA}`,
    dollars_recoverable: Math.max(0, +recoverable.toFixed(2)),
  });
}
leaks.sort((a, b) => b.dollars_recoverable - a.dollars_recoverable);

return [{ json: {
  date_preset: cfg.DATE_PRESET,
  audience_network_totals: {
    spend: +anSpend.toFixed(2), results: anResults,
    cpa: anResults > 0 ? +(anSpend / anResults).toFixed(2) : null,
  },
  benchmark_cpa: benchCPA,
  leak_count: leaks.length,
  total_recoverable: +leaks.reduce((n, l) => n + l.dollars_recoverable, 0).toFixed(2),
  leaks,
} }];

// Ask Claude to turn the Audience Network leak list into a prioritized action plan.
const d = $json;
const system = 'You are a senior paid-social analyst. You are given Audience Network (AN) delivery slices from a Meta ad account, judged against the account non-AN cost-per-result benchmark. For each slice give one concrete action: EXCLUDE Audience Network, KEEP (with why), or INVESTIGATE. Rank by dollars recoverable. Be terse. Return ONLY valid JSON, no prose, no markdown fences.';
const user = 'Non-AN benchmark CPA: $' + d.benchmark_cpa + '. Total recoverable: $' + d.total_recoverable + '.\n\nAudience Network leaks:\n' + JSON.stringify(d.leaks) + '\n\nReturn JSON exactly: {"summary":"one sentence","ranked":[{"placement":"","recoverable":0,"action":"exclude|keep|investigate","why":""}]}';
const body = { model: 'claude-haiku-4-5', max_tokens: 3000, system, messages: [{ role: 'user', content: user }] };
return [{ json: { body, _ctx: d } }];

// Print a readable Audience Network leak report. Swap this node for Slack or email to auto-deliver.
const ctx = $('Build AI action prompt').first().json._ctx || {};
function aiJson(fallback) {
  const t = ($json.content && $json.content[0] && $json.content[0].text) || '';
  let s = String(t).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const m = s.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return fallback;
}
const ai = aiJson({ summary: 'AI response could not be parsed.', ranked: [] });

const lines = [];
lines.push('AUDIENCE NETWORK LEAK REPORT (' + (ctx.date_preset || '') + ')');
lines.push('Non-AN benchmark CPA: $' + ctx.benchmark_cpa);
lines.push('Leaks: ' + (ctx.leak_count || 0) + ' | Recoverable: $' + (ctx.total_recoverable || 0));
lines.push('');
lines.push(ai.summary || '');
lines.push('');
for (const r of (ai.ranked || [])) {
  lines.push('- [' + String(r.action || '').toUpperCase() + '] ' + r.placement + '  ($' + r.recoverable + ')');
  if (r.why) lines.push('    ' + r.why);
}
return [{ json: { report: lines.join('\n'), leaks: ctx.leaks || [], ai } }];
